package ru.lct.teplokontur.optimization;
import org.junit.jupiter.api.Test;import org.locationtech.jts.geom.*;import ru.lct.teplokontur.config.CompetitionProperties;import ru.lct.teplokontur.domain.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class GeneralizationSmokeTest {
 private final GeometryFactory gf=new GeometryFactory();
 @Test void worksForLoadedScenariosWithoutKnownIds2dAnd3d(){for(int k=0;k<2;k++){InputSnapshot s=fixture(k);UniversalOptimizer o=new UniversalOptimizer(new CompetitionProperties());List<NetworkPlan> a=o.optimize(s,RunMode.TWO_D),b=o.optimize(s,RunMode.DEPTH);assertFalse(a.isEmpty());assertFalse(b.isEmpty());assertTrue(a.stream().allMatch(x->x.validation.passed));assertTrue(b.stream().allMatch(x->x.validation.passed));assertTrue(a.stream().anyMatch(x->x.unconnected.size()<s.terminals.size()));}}
 private InputSnapshot fixture(int shift){InputSnapshot s=new InputSnapshot(1000+shift);s.source=pt(0+shift*1000,0);InputSnapshot.InputFeature uploaded=new InputSnapshot.InputFeature();uploaded.sequence=1;uploaded.id="uploaded-"+shift;uploaded.objectType="heat_network";s.features.add(uploaded);InputSnapshot.ExistingEdge e=new InputSnapshot.ExistingEdge();e.id="network-"+UUID.randomUUID();e.upstream="source-"+shift;e.dn=300;e.flow=40;e.geometry=ls(0+shift*1000,0,300+shift*1000,0);s.network.add(e);for(int i=0;i<4;i++){InputSnapshot.Terminal t=new InputSnapshot.Terminal();t.oksId="hidden-oks-"+shift+"-"+i;t.pointId="entry-"+UUID.randomUUID();t.flow=10+i*2;t.point=pt(40+shift*1000+i*60,70+(i%2)*35);s.terminals.add(t);}return s;}
 private Point pt(double x,double y){return gf.createPoint(new Coordinate(x,y));}private LineString ls(double x1,double y1,double x2,double y2){return gf.createLineString(new Coordinate[]{new Coordinate(x1,y1),new Coordinate(x2,y2)});}
}
